import{_ as e,o as l,c as i,a2 as t}from"./chunks/framework.BQ1gajhD.js";const p=JSON.parse('{"title":"北京骑行指南","description":"","frontmatter":{},"headers":[],"relativePath":"guide/cycling.md","filePath":"guide/cycling.md","lastUpdated":1787045959000}'),r={name:"guide/cycling.md"};function o(n,a,c,d,s,h){return l(),i("div",null,[...a[0]||(a[0]=[t('<h1 id="北京骑行指南" tabindex="-1">北京骑行指南 <a class="header-anchor" href="#北京骑行指南" aria-label="Permalink to &quot;北京骑行指南&quot;">​</a></h1><blockquote><p>&quot;老城不大，骑车刚刚好。&quot;</p></blockquote><h2 id="为什么骑车" tabindex="-1">为什么骑车 <a class="header-anchor" href="#为什么骑车" aria-label="Permalink to &quot;为什么骑车&quot;">​</a></h2><p>北京二环内的胡同片区步行走不完、坐车进不去，共享单车是最灵活的打开方式。骑行速度慢，恰好配合胡同的节奏：随时停下拍门墩、买糖葫芦、钻进小店。</p><h2 id="经典路线一-胡同环线-约6公里-2-3小时" tabindex="-1">经典路线一：胡同环线（约6公里，2-3小时） <a class="header-anchor" href="#经典路线一-胡同环线-约6公里-2-3小时" aria-label="Permalink to &quot;经典路线一：胡同环线（约6公里，2-3小时）&quot;">​</a></h2><p><strong>路线</strong>：五道营胡同 → 雍和宫外墙 → 国子监街 → 钟鼓楼 → 什刹海 → 南锣鼓巷</p><ul><li>五道营胡同：独立小店与咖啡馆，早上人少最好逛</li><li>国子监街：两侧槐树成荫，红墙配匾额，是北京最上镜的街巷之一</li><li>钟鼓楼：登不登楼都值得在楼下绕一圈</li><li>什刹海：银锭桥一带骑行需注意人流，傍晚看日落最佳</li></ul><h2 id="经典路线二-城南文化线-约8公里-3小时" tabindex="-1">经典路线二：城南文化线（约8公里，3小时） <a class="header-anchor" href="#经典路线二-城南文化线-约8公里-3小时" aria-label="Permalink to &quot;经典路线二：城南文化线（约8公里，3小时）&quot;">​</a></h2><p><strong>路线</strong>：前门大街 → 大栅栏 → 琉璃厂 → 杨梅竹斜街 → 东交民巷</p><ul><li>前门大街：骑行主干道，两侧老字号</li><li>大栅栏/琉璃厂：街巷窄，建议推车慢逛，看老店铺与笔墨纸砚</li><li>杨梅竹斜街：最文艺的一段，安静、小店有格调</li><li>东交民巷：西洋建筑群，傍晚光线最好</li></ul><h2 id="进阶路线-首钢园-约10公里-半天" tabindex="-1">进阶路线：首钢园（约10公里，半天） <a class="header-anchor" href="#进阶路线-首钢园-约10公里-半天" aria-label="Permalink to &quot;进阶路线：首钢园（约10公里，半天）&quot;">​</a></h2><p>首钢园园区开阔、路况好，工业遗存与冬奥场馆是绝佳骑行背景。地铁6号线或11号线可达，园内可租车，建议避开周末下午人流高峰。</p><h2 id="骑行提示" tabindex="-1">骑行提示 <a class="header-anchor" href="#骑行提示" aria-label="Permalink to &quot;骑行提示&quot;">​</a></h2><ul><li>共享单车在胡同片区投放充足，但早晚高峰可能难找，可步行至主街再扫车</li><li>什刹海、南锣鼓巷核心区周末人多，骑行请减速避让行人</li><li>北京夏季午后炎热，建议 17:00 后出发，还能衔接夜景</li></ul>',14)])])}const _=e(r,[["render",o]]);export{p as __pageData,_ as default};
